100  void update_font(ASS_Renderer *render_priv)
   101  {
   102      unsigned val;
   103      ASS_FontDesc desc;
   104
   105      desc.family = render_priv->state.family;
   106      if (!desc.family.str)
   107          return;
   108      if (desc.family.len && desc.family.str[0] == '@') {
   109          desc.vertical = 1;
   110          desc.family.str++;
   111          desc.family.len--;
   112      } else {
   113          desc.vertical = 0;
   114      }
   115
   116      val = render_priv->state.bold;
   117      // 0 = normal, 1 = bold, >1 = exact weight
   118      if (val == 1 || val == -1)
   119          val = 700;               // bold
   120      else if (val <= 0)
   121          val = 400;               // normal
   122      desc.bold = val;
   123
   124      val = render_priv->state.italic;
   125      if (val == 1)
   126          val = 100;              // italic
   127      else if (val <= 0)
   128          val = 0;                // normal
   129      desc.italic = val;
   130
   131      ass_cache_dec_ref(render_priv->state.font);
   132      render_priv->state.font = ass_font_new(render_priv, &desc);
   133  }
